def backfill_curriculum_course_entries(apps, schema_editor):
    """Copy legacy course membership into the metadata-bearing through model.

    This is additive: it neither deletes nor rewrites historic Course rows,
    registrations, allocations or the legacy M2M.  It is therefore safe for
    production databases that already contain programme handbook versions.
    """
    Course = apps.get_model("portal", "Course")
    CurriculumCourse = apps.get_model("portal", "CurriculumCourse")
    entries = []
    seen = set()
    for course in Course.objects.all().prefetch_related("curricula"):
        curricula = list(course.curricula.all())
        if course.curriculum_id:
            curricula.append(course.curriculum)
